import { serve } from 'npm:https://deno.land/std@0.177.0/http/server.ts';
import { createClient } from 'npm:@supabase/supabase-js';
import { generateSense } from './moduleA.ts';
import { callGemini } from './utils/gemini.ts';
import { buildSynthesisPrompt, ARCHETYPES } from '../../../src/core/api/SynthesisPromptsBackend.ts';
import { buildDeltaPrompt, DeltaMissing } from '../../../src/core/api/DeltaPromptBackend.ts';
import { buildVisualPrompt } from '../../../src/core/api/VisualPromptsBackend.ts';
import { injectSenseMeta } from '../../../src/core/api/injectSenseMeta.ts';
import { SynthesisRequest, GeminiSynthesisOutput, SenseAIPayload, RawSenseAIOutput } from './types.ts';

const corsHeaders = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

const _genderedLangs = new Set(['fr', 'de', 'es', 'it', 'pt']);
const _verbGroupLangs = new Set(['fr', 'es', 'it', 'pt']);

serve(async (req: Request) => {
    // 1. CORS Preflight
    if (req.method === 'OPTIONS') {
        return new Response('ok', { headers: corsHeaders });
    }

    try {
        const body: SynthesisRequest = await req.json();
        const {
            input_1_id,
            input_2_id,
            lang,
            max_level = 'B2',
            target_languages = ['en'],
            personaId = 'default',
            personaNarrative,
            visual_id = 'default'
        } = body;

        // ① UUID 格式验证 + 非空检查
        const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
        if (!input_1_id || !input_2_id || !uuidRegex.test(input_1_id) || !uuidRegex.test(input_2_id)) {
            return new Response(JSON.stringify({ error: 'INVALID_INPUT', message: 'Missing or invalid UUIDs' }), {
                headers: { ...corsHeaders, 'Content-Type': 'application/json' },
                status: 400
            });
        }

        const sortedUids = [input_1_id, input_2_id].sort();

        // ② 初始化 Supabase Client (Service Role for Admin read/writes, user identity in context if passed)
        // Assume req has user identity optionally, but here we run elevated DB tasks
        const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
        const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
        const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

        // Mock discoverer ID for Edge func (if not passing auth correctly)
        // Normally extract from req headers via anon key auth token
        const discovererUserId = '00000000-0000-0000-0000-000000000000';

        // ③ 查 synthesis_cache (hit or miss)
        // method_id = 1 (default standard merge) slot_index = 1
        const { data: cacheRow, error: cacheErr } = await supabaseAdmin
            .from('synthesis_cache')
            .select('sense_id, synthesis_reason')
            .eq('uid1_sorted', sortedUids[0])
            .eq('uid2_sorted', sortedUids[1])
            .eq('method_id', 1)
            .eq('slot_index', 1)
            .maybeSingle();

        if (cacheErr && cacheErr.code !== 'PGRST116') {
            console.error('Cache Query Error:', cacheErr);
            throw new Error('DATABASE_ERROR');
        }

        if (cacheRow && cacheRow.sense_id) {
            // ④ Cache Hit 聚合逻辑
            const { data: senseRow } = await supabaseAdmin.from('senses').select('*').eq('uid', cacheRow.sense_id).single();
            const { data: shellRow } = await supabaseAdmin.from('sense_word_shells').select('*').eq('sense_id', cacheRow.sense_id).maybeSingle();
            const { data: visuals } = await supabaseAdmin.from('sense_visuals').select('*').eq('sense_id', cacheRow.sense_id);
            const { data: flavors } = await supabaseAdmin.from('sense_flavor_texts').select('*').eq('sense_id', cacheRow.sense_id);

            if (!senseRow) {
                // Orphaned cache handle
                throw new Error('ORPHANED_CACHE');
            }

            const existingShells = shellRow?.shells || {};
            const existingTraits = shellRow?.traits || {};
            const existingWordFamily = senseRow.word_family || {};
            const activeVisual = visuals?.find(v => v.id === visual_id);
            const activeFlavor = flavors?.find(f => f.persona === personaId);

            // 检查版本升级缺失 (Delta)
            const missing: DeltaMissing = {
                langs: [],
                personas: [],
                wordFamilyLangs: [],
                traitLangs: []
            };

            for (const tl of target_languages) {
                if (!existingShells[tl] || !senseRow.meaning?.[tl]) {
                    missing.langs.push(tl);
                } else {
                    if (!existingWordFamily[tl]) {
                        missing.wordFamilyLangs.push(tl);
                    }
                    // Traits Check - minimal validation
                    const shellValues = Object.values(existingShells);
                    const pos = shellValues.length > 0 ? (shellValues[0] as any).pos.value || 'n.' : 'n.';
                    const traitList = existingTraits[tl] || [];
                    let traitMissing = false;

                    if (pos === 'n.' && _genderedLangs.has(tl)) {
                        if (!traitList.some((t: any) => t.traitId === 'gender')) traitMissing = true;
                    } else if ((pos === 'v.' || pos === 'v.i.' || pos === 'v.t.') && _verbGroupLangs.has(tl)) {
                        if (!traitList.some((t: any) => t.traitId === 'verb_group')) traitMissing = true;
                    }

                    if (traitMissing) {
                        missing.traitLangs.push(tl);
                    }
                }
            }

            if (!activeFlavor && missing.langs.length === 0) { // If langs is empty, it means we don't naturally fetch the new persona
                missing.personas.push(personaId);
            }

            // Sync blocking Delta check
            let updatedPayload: any = null; // Normally we'd deep merge the db records + delta generated ones
            const totalMissing = missing.langs.length + missing.personas.length + missing.wordFamilyLangs.length + missing.traitLangs.length;

            if (totalMissing > 0) {
                // Here we might normally implement a DB level short-lived lock [sense_id_delta_lock].
                console.log('Delta Triggered for cache hit:', missing);
                const exShellsAnchor = Object.fromEntries(
                    Object.entries(existingShells).map(([k, v]: [string, any]) => [k, typeof v.text === 'object' ? v.text.value : v.text])
                );

                const { systemPrompt: sys, userPrompt: usr } = buildDeltaPrompt({
                    concept: senseRow.concept || 'Unknown',
                    definition: senseRow.meaning?.['en']?.value || '', // Simplified definition fetch for prompt
                    existingShells: exShellsAnchor,
                    missing,
                    personaId,
                    personaNarrative
                });

                const rawDelta = await callGemini({ systemPrompt: sys, userPrompt: usr });
                const deltaJson = injectSenseMeta(JSON.parse(rawDelta.replace(/^```[a-z]*\n/i, '').replace(/\n```$/, '').trim()));
                // UPSERT delta updates - left simplified as this is a skeleton router pattern
                // We assume `deltaJson` correctly aligns with SenseAIPayload 
            }

            // Non-blocking Visual Check
            if (!activeVisual) {
                (async () => {
                    try {
                        const { systemPrompt: vSys, userPrompt: vUser } = buildVisualPrompt({
                            concept: senseRow.concept || 'Unknown',
                            definition: senseRow.meaning?.['en']?.value || '',
                            visualId: visual_id
                        });
                        const visualRawText = await callGemini({ systemPrompt: vSys, userPrompt: vUser });
                        let code = visualRawText.split('// --- CODE BELOW ---')[1]?.trim() || visualRawText.trim();
                        code = code.replace(/^```(tsx|jsx|ts|js)?\n/i, '').replace(/\n```$/, '').trim();

                        await supabaseAdmin.from('sense_visuals').insert({
                            sense_id: cacheRow.sense_id,
                            id: visual_id,
                            payload: code,
                            meta: { stability: 50.0, firstDiscoverer: discovererUserId, firstDiscoveredAt: Date.now() }
                        });
                    } catch (e) { }
                })();
            }

            return new Response(JSON.stringify({
                synthesisReason: cacheRow.synthesis_reason,
                sense: { ...senseRow, shells: shellRow?.shells }, // Simplified output assembly
                visual: activeVisual || null,
                cached: true
            }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
        }

        // ⑤ Cache Miss 流程

        // Fetch definition of the two roots to provide to SynthesisPrompt
        // (Assuming senses table stores all base roots too)
        const { data: r1 } = await supabaseAdmin.from('senses').select('concept, meaning').eq('uid', sortedUids[0]).maybeSingle();
        const { data: r2 } = await supabaseAdmin.from('senses').select('concept, meaning').eq('uid', sortedUids[1]).maybeSingle();

        if (!r1 || !r2) throw new Error('INPUT_NOT_FOUND');

        const defA = r1.meaning?.['en']?.value || 'Unknown';
        const defB = r2.meaning?.['en']?.value || 'Unknown';

        // Attempt 1: Contextual Archetype (pick randomly 1-6)
        const randomArchetype = Math.floor(Math.random() * 6) + 1;
        const p1 = buildSynthesisPrompt({
            nameA: r1.concept, defA,
            nameB: r2.concept, defB,
            lang: target_languages[0] || 'en',
            maxLevel: max_level,
            archetype: randomArchetype as any
        });

        let outputText = await callGemini({ systemPrompt: p1.systemPrompt, userPrompt: p1.userPrompt });
        let aijson: GeminiSynthesisOutput = JSON.parse(outputText.replace(/^```[a-z]*\n/i, '').replace(/\n```$/, '').trim());

        if (aijson.outcome === 'failure') {
            // Attempt 2: Free AI (no archetype limit)
            const p2 = buildSynthesisPrompt({
                nameA: r1.concept, defA,
                nameB: r2.concept, defB,
                lang: target_languages[0] || 'en',
                maxLevel: max_level
            });
            outputText = await callGemini({ systemPrompt: p2.systemPrompt, userPrompt: p2.userPrompt });
            aijson = JSON.parse(outputText.replace(/^```[a-z]*\n/i, '').replace(/\n```$/, '').trim());

            if (aijson.outcome === 'failure') {
                return new Response(JSON.stringify({ error: 'NO_SYNERGY', message: 'The elements cannot be synthesized together rationally.' }), {
                    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
                    status: 400
                });
            }
        }

        // 去重检查
        const exactConcept = aijson.result_concept.trim();
        const { data: dupe } = await supabaseAdmin.from('senses').select('uid').ilike('concept', exactConcept).maybeSingle();

        let coreOutputData;

        if (dupe) {
            // It's a late cache hit essentially
            const { data: senseRow } = await supabaseAdmin.from('senses').select('*').eq('uid', dupe.uid).single();
            // Assuming simplified response as cache
            coreOutputData = { sense: { ...senseRow }, visual: null };

            // Record this combination in cache to point to existing entity
            await supabaseAdmin.from('synthesis_cache').insert({
                uid1_sorted: sortedUids[0],
                uid2_sorted: sortedUids[1],
                method_id: 1,
                slot_index: 1,
                sense_id: dupe.uid,
                synthesis_reason: aijson.synthesis_reason
            });
        } else {
            // Fresh Generate
            coreOutputData = await generateSense(
                aijson.result_concept,
                aijson.result_definition_en,
                body,
                discovererUserId,
                supabaseAdmin
            );

            await supabaseAdmin.from('synthesis_cache').insert({
                uid1_sorted: sortedUids[0],
                uid2_sorted: sortedUids[1],
                method_id: 1,
                slot_index: 1,
                sense_id: coreOutputData.sense.uid,
                synthesis_reason: aijson.synthesis_reason
            });
        }

        return new Response(JSON.stringify({
            synthesisReason: aijson.synthesis_reason,
            sense: coreOutputData.sense,
            visual: coreOutputData.visual,
            cached: false
        }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });

    } catch (error: any) {
        console.error('Edge function caught error:', error);
        const errType = error.message === 'DATABASE_ERROR' ? 'DATABASE_ERROR' :
            error.message === 'INPUT_NOT_FOUND' ? 'INPUT_NOT_FOUND' : 'GENERATION_FAILED';
        return new Response(JSON.stringify({ error: errType, message: error.message }), {
            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
            status: errType === 'INPUT_NOT_FOUND' ? 404 : 500
        });
    }
});

import { callGemini } from './utils/gemini.ts';
import { buildSensePrompt } from '../../../src/core/api/SensePromtBackend.ts';
import { buildVisualPrompt } from '../../../src/core/api/VisualPromptsBackend.ts';
// We assume we can import these ts files directly in Deno as long as paths resolve
import { injectSenseMeta } from '../../../src/core/api/injectSenseMeta.ts';
import { RawSenseAIOutput, SenseAIPayload, SynthesisRequest } from './types.ts';

// Web crypto API runs in Deno Edge Functions
export const generateUUID = () => crypto.randomUUID();

/**
 * 验证并清理 AI 返回的 JSON 字符串
 */
function parseGeminiJson<T>(rawText: string): T {
    // 移除可能存在的 markdown 代码块
    const cleaned = rawText.replace(/^```[a-z]*\n/i, '').replace(/\n```$/, '').trim();
    return JSON.parse(cleaned) as T;
}

/**
 * Basic security / structure check for generated TSX payload
 */
function validateVisualPayload(payload: string): boolean {
    // Check if it exports default
    if (!payload.includes('export default')) return false;
    // Disallow hooks as per secure rules
    if (payload.includes('useEffect') || payload.includes('useState')) {
        console.warn('VisualPrompt validation failed: found hooks hook');
        // Currently we just log, but let's strictly reject it
        return false;
    }
    return true;
}

/**
 * Module A: 核心 Sense 生成业务流
 * - 调用 SensePrompt 生成概念本身 (Blocking)
 * - 注入 Meta, 写入 3 张表 (senses, sense_word_shells, sense_flavor_texts)
 * - 立刻返回已生成的 Sense 内容
 * - 后台异步触发 VisualPrompt (Non-blocking), 并写 sense_visuals
 */
export async function generateSense(
    concept: string,
    definition: string,
    request: SynthesisRequest,
    discovererUserId: string,
    supabaseAdmin: any // uses service_role client for DB inserts
): Promise<{ sense: SenseAIPayload & { uid: string }; visual: any }> {
    const { max_level = 'B2', target_languages = ['en'], personaId = 'default', personaNarrative, visual_id = 'default' } = request;

    // ① 生成新 UID
    const uid = generateUUID();

    // ② 构建并发送 Sense Prompt
    const { systemPrompt, userPrompt } = buildSensePrompt({
        concept,
        definition,
        maxLevel: max_level,
        target_languages,
        personaId,
        personaNarrative
    });

    const aiRawText = await callGemini({ systemPrompt, userPrompt });

    // ③ 解析 JSON 并注入 UID
    let rawJson: RawSenseAIOutput;
    try {
        rawJson = parseGeminiJson<RawSenseAIOutput>(aiRawText);
    } catch (err) {
        console.error('Failed to parse Sense AI JSON:', aiRawText);
        throw new Error('GENERATION_FAILED');
    }

    // 立即调用 injectSenseMeta 注入 `{ stability: 100.0 }` 等元数据
    const sensePayload: SenseAIPayload = injectSenseMeta(rawJson);

    const now = Date.now();

    // ④ 写入 DB
    // A. senses 表
    const { error: senseError } = await supabaseAdmin.from('senses').insert({
        uid,
        fingerprint: sensePayload.fingerprint.value, // value extract
        ontology: sensePayload.ontology.value,
        meaning: Object.fromEntries(Object.entries(sensePayload.meaning).map(([k, v]) => [k, v.value])),
        frequency: sensePayload.frequency.value,
        // word_family 使用注入 meta 后的完整字段
        word_family: sensePayload.wordFamily,

        // 核心：由后端在这里直接写入第一发现人元数据，防篡改
        meta: {
            firstDiscoverer: discovererUserId,
            firstDiscoveredAt: now,
        }
    });

    if (senseError) {
        console.error('Failed to insert senses DB', senseError);
        throw new Error('GENERATION_FAILED');
    }

    // B. sense_word_shells 表
    const { error: shellsError } = await supabaseAdmin.from('sense_word_shells').insert({
        sense_id: uid,
        shells: sensePayload.shells, // 包含 meta 注入后的整个 shells 对象
        traits: sensePayload.traits || null // traits 可能可选
    });

    if (shellsError) {
        console.error('Failed to insert sense_word_shells DB', shellsError);
        // Best effort continuation or abort? Usually better to fail loudly.
        throw new Error('GENERATION_FAILED');
    }

    // C. sense_flavor_texts 表
    // 每 persona 插入一行
    const flavorInserts = sensePayload.flavorText.map((flavor: any) => ({
        sense_id: uid,
        persona: flavor.persona,
        texts: Object.fromEntries(Object.entries(flavor.text).map(([k, v]: [string, any]) => [k, v.value])),
        examples: Object.fromEntries(Object.entries(flavor.example).map(([k, v]: [string, any]) => [k, v.value])),
    }));

    if (flavorInserts.length > 0) {
        const { error: flavorError } = await supabaseAdmin.from('sense_flavor_texts').insert(flavorInserts);
        if (flavorError) console.error('Failed to insert sense_flavor_texts DB', flavorError);
    }

    // ⑤ 异步 Non-blocking Visual 补全
    // Fire and forget
    (async () => {
        try {
            const { systemPrompt: vSys, userPrompt: vUser } = buildVisualPrompt({
                concept,
                definition,
                visualId: visual_id
            });
            const visualRawText = await callGemini({ systemPrompt: vSys, userPrompt: vUser });

            // Extract code:
            const codeMatch = visualRawText.split('// --- CODE BELOW ---');
            let code = codeMatch.length > 1 ? codeMatch[1].trim() : visualRawText.trim();
            // remove markdown wrappers if any
            code = code.replace(/^```(tsx|jsx|ts|js)?\n/i, '').replace(/\n```$/, '').trim();

            if (validateVisualPayload(code)) {
                // 写 DB
                const { error: visErr } = await supabaseAdmin.from('sense_visuals').insert({
                    sense_id: uid,
                    id: visual_id,
                    payload: code,
                    meta: {
                        stability: 50.0,
                        firstDiscoverer: discovererUserId,
                        firstDiscoveredAt: now
                    }
                });
                if (visErr) console.error('Silent failure writing visual DB:', visErr);
            }
        } catch (e) {
            console.error('Silent failure in Visual async task:', e);
        }
    })();

    // ⑥ 立即返回核心文本结构
    return {
        sense: { ...sensePayload, uid },
        visual: null // loading placeholder
    };
}

/**
 * Edge Function Type Definitions for Synthesize-Sense
 */

export type ArchetypeId = 1 | 2 | 3 | 4 | 5 | 6;

export interface SynthesisRequest {
    input_1_id: string;
    input_2_id: string;
    lang: string;
    max_level?: string;
    target_languages?: string[];
    personaId?: string;
    personaNarrative?: string;
    visual_id?: string;
}

export type SynthesisErrorCode =
    | 'NO_SYNERGY'
    | 'OFFENSIVE'
    | 'TOO_COMPLEX'
    | 'INPUT_NOT_FOUND'
    | 'GENERATION_FAILED'
    | 'LLM_ERROR';

export interface SynthesisFailureResponse {
    error: SynthesisErrorCode;
    message?: string;
}

// ============================================================================
// AI Prompt Outputs
// ============================================================================

export interface GeminiSynthesisOutput {
    outcome: 'success' | 'failure';
    result_concept: string;
    result_definition_en: string;
    archetype_used: number;
    synthesis_reason: string | Record<string, string>;
    failure_code?: string;
}

// ============================================================================
// Payload Types
// ============================================================================

export interface RawShell {
    text: string;
    pronunciation: string;
    pos: string;
    level: string;
    wordFrequency: number;
}

export interface RawWordFamilyDerivation {
    word: string;
    pos: string;
}

export interface RawWordFamily {
    root: string;
    derivations: RawWordFamilyDerivation[];
}

export interface RawTrait {
    traitId: string;
    value: string | string[];
}

/**
 * RawSenseAIOutput (AI 纯值输出，无 meta 字段)
 */
export interface RawSenseAIOutput {
    fingerprint: string;
    frequency: number;
    ontology: string;
    meaning: Record<string, string>;
    flavorText: Array<{
        persona: string;
        text: Record<string, string>;
        example: Record<string, string>;
    }>;
    shells: Record<string, RawShell[]>;
    wordFamily: Record<string, RawWordFamily>;
    traits?: Record<string, RawTrait[]>;
}

// ============================================================================
// Meta-Injected Types
// ============================================================================

export interface EntryMetadata {
    stability: number;
}

export interface MetaInjected<T> {
    value: T;
    meta: EntryMetadata;
}

export interface MetaShell {
    text: MetaInjected<string>;
    pronunciation: MetaInjected<string>;
    pos: MetaInjected<string>;
    level: MetaInjected<string>;
    wordFrequency: MetaInjected<number>;
    meta: EntryMetadata; // Shell-level meta
}

export interface MetaWordFamilyDerivation {
    word: string;
    pos: string;
}

export interface MetaWordFamily {
    root: string;
    derivations: MetaWordFamilyDerivation[];
    meta: EntryMetadata;
}

export interface MetaTrait {
    traitId: string;
    value: string | string[];
    meta: EntryMetadata;
}

/**
 * SenseAIPayload (后端注入 meta 后)
 */
export interface SenseAIPayload {
    fingerprint: MetaInjected<string>;
    frequency: MetaInjected<number>;
    ontology: MetaInjected<string>;
    meaning: Record<string, MetaInjected<string>>;
    flavorText: Array<{
        persona: string;
        text: Record<string, MetaInjected<string>>;
        example: Record<string, MetaInjected<string>>;
        meta: EntryMetadata;
    }>;
    shells: Record<string, MetaShell[]>;
    wordFamily: Record<string, MetaWordFamily>;
    traits?: Record<string, MetaTrait[]>;
}

export interface SynthesisSuccessResponse {
    synthesisReason: string | Record<string, string>;
    sense: SenseAIPayload & { uid: string };
    visual: any; // visual details or null if pending
    cached: boolean;
}

import { GoogleGenerativeAI } from 'npm:@google/generative-ai';

interface CallGeminiParams {
    systemPrompt: string;
    userPrompt: string;
    model?: string;
    temperature?: number;
    responseMimeType?: string;
    maxTokens?: number;
}

/**
 * Helper to call Gemini AI with a timeout.
 */
async function fetchWithTimeout<T>(
    promise: Promise<T>,
    timeoutMs: number
): Promise<T> {
    let timer: number | undefined;
    const timeoutPromise = new Promise<never>((_, reject) => {
        timer = setTimeout(() => {
            reject(new Error(`Timeout of ${timeoutMs}ms exceeded`));
        }, timeoutMs);
    });

    try {
        return await Promise.race([promise, timeoutPromise]);
    } finally {
        if (timer) clearTimeout(timer);
    }
}

/**
 * 封装对 Google Gemini API 的调用。
 * 支持传入 systemPrompt 和 userPrompt，默认使用 gemini-3.0-flash 模型。
 * 包含 1 次自动重试和 60s 超时控制。
 */
export async function callGemini(params: CallGeminiParams): Promise<string> {
    const {
        systemPrompt,
        userPrompt,
        model = 'gemini-3.0-flash',
        temperature = 1.0,
        responseMimeType = 'application/json',
        maxTokens = 10000,
    } = params;

    const apiKey = Deno.env.get('GEMINI_API_KEY');
    if (!apiKey) {
        throw new Error('Missing GEMINI_API_KEY environment variable.');
    }

    const genAI = new GoogleGenerativeAI(apiKey);
    const generativeModel = genAI.getGenerativeModel({
        model,
        systemInstruction: systemPrompt,
        generationConfig: {
            temperature,
            maxOutputTokens: maxTokens,
            responseMimeType,
        },
    });

    const attemptCall = async () => {
        const result = await fetchWithTimeout(
            generativeModel.generateContent(userPrompt),
            60000 // 60 seconds timeout
        );
        const text = result.response.text();
        return text;
    };

    try {
        // Attempt 1
        return await attemptCall();
    } catch (error) {
        console.error(`[callGemini] Attempt 1 failed: ${error instanceof Error ? error.message : String(error)}. Retrying...`);
        // Attempt 2 (1 retry)
        try {
            return await attemptCall();
        } catch (retryError) {
            console.error(`[callGemini] Attempt 2 failed: ${retryError instanceof Error ? retryError.message : String(retryError)}.`);
            throw retryError;
        }
    }
}

/**
 * src/core/api/prompts.ts
 */

export type ArchetypeId = 1 | 2 | 3 | 4 | 5 | 6;

// 定义每种 Archetype 的基础描述和高亮描述
